-- clotere-pro — migration 0029 : 33 domaines avocat (barre de recherche Alexia) et leurs sous-domaines,
-- sujets traités par motif (motifs.specialite_ids) et sujet choisi par le client (bookings.specialite_id).
-- Les ids de 0008 sont conservés quand le sujet est le même ; les autres sont repris puis supprimés.

alter table domaines add column if not exists description text;
alter table motifs add column if not exists specialite_ids text[] not null default '{}';
alter table bookings add column if not exists specialite_id text references specialites(id) on delete set null;

-- Domaines et sous-domaines ------------------------------------------------

-- Reprise des spécialités cochées par les avocats -----------------------------

-- Motifs rattachés aux domaines supprimés
update motifs set domaine_id = 'avocat-societes' where domaine_id = 'avocat-entreprises';
update motifs set domaine_id = null where domaine_id = 'avocat-autres';

-- Nettoyage : anciennes spécialités et domaines avocat qui n'existent plus
